def img(src, alt, klass='', priority=False, extra=''):
    return f'<img class="{klass}" src="/assets/{src}" alt="{escape(alt,quote=True)}" loading="{"eager" if priority else "lazy"}" decoding="async" {"fetchpriority=high" if priority else ""} {extra}>'

def meta(title, description, slug, og):
    url=BASE+('/'+slug if slug else '/')
    ld={'@context':'https://schema.org','@type':'ApartmentComplex','name':'IthacaHome — Plaza East and SummerHill','url':BASE,'description':'Apartments and townhouses on East Hill, near Cornell University.','telephone':'+1-607-379-6001','email':'rentals@ithacahome.com','address':{'@type':'PostalAddress','streetAddress':'222 Summerhill Drive','addressLocality':'Ithaca','addressRegion':'NY','postalCode':'14850','addressCountry':'US'}}
    if slug:
        ld={'@context':'https://schema.org','@type':'WebPage','name':title,'url':url,'isPartOf':{'@type':'WebSite','name':'IthacaHome','url':BASE}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f4ef"><meta name="description" content="{escape(description,quote=True)}"><title>{escape(title)}</title><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/assets/{og}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps(ld,separators=(',',':'))}</script></head>'''


def header(current=''):
    def item(page,text):
        return f'<a href="/{page}" {"aria-current=page" if current==page else ""}>{text}</a>'
    return f'''<a class="skip-link" href="#content">Skip to content</a><div class="reading-progress" aria-hidden="true"></div><header class="header" id="header"><div class="header-inner"><a href="/" class="wordmark" aria-label="IthacaHome home"><span class="wordmark-roof" aria-hidden="true"></span><span>ITHACA<span class="wordmark-home">HOME</span></span></a><nav class="nav-desktop" aria-label="Main navigation">{item(PLAZA,'Plaza East')}{item(SUMMER,'SummerHill')}{item('neighborhood.html','The location')}</nav><a href="/contact.html" class="nav-action">Schedule a tour</a><button class="nav-toggle" id="nav-toggle" type="button" aria-expanded="false" aria-controls="nav-mobile" aria-label="Open navigation"><span></span><span></span></button></div><nav class="nav-mobile" id="nav-mobile" aria-label="Mobile navigation" inert><a href="/">Home</a>{item(PLAZA,'Plaza East')}{item(SUMMER,'SummerHill')}{item('neighborhood.html','The location')}<a href="/contact.html" class="mobile-book">Schedule a tour</a><div class="mobile-contact"><a href="tel:+16073796001">(607) 379-6001</a><a href="mailto:rentals@ithacahome.com">rentals@ithacahome.com</a></div></nav></header>'''

def footer():
    return '''<footer class="footer"><div class="container"><div class="footer-top"><div><a href="/" class="footer-brand">ITHACA<span>HOME</span></a><p>Plaza East apartments and SummerHill townhouses.<br>East Hill, Ithaca, New York.</p></div><div class="footer-cta"><p>Interested in a residence?</p><a href="/contact.html" class="button button-cream">Arrange a visit</a></div></div><div class="footer-bottom"><span>222 Summerhill Drive, Ithaca, NY 14850</span><a href="tel:+16073796001">(607) 379-6001</a><a href="mailto:rentals@ithacahome.com">rentals@ithacahome.com</a><a href="/privacy.html">Privacy</a><span>© <span id="year">2026</span> IthacaHome</span></div></div></footer>'''

def lightbox():
    return '''<dialog class="lightbox" id="lightbox" aria-label="Property image viewer"><div class="lightbox-top"><span id="lightbox-count">01 / 12</span><button class="lightbox-close" type="button" aria-label="Close gallery">Close</button></div><div class="lightbox-stage"><button class="lightbox-prev" type="button" aria-label="Previous photo">Previous</button><figure><img id="lightbox-img" alt=""><figcaption id="lightbox-caption"></figcaption></figure><button class="lightbox-next" type="button" aria-label="Next photo">Next</button></div></dialog>'''

def wrap(body,slug,title,description,og,current='',pageclass=''):
    return meta(title,description,slug,og)+f'<body data-page="{pageclass or slug or "home"}">'+header(current)+f'<main id="content">{body}</main>'+footer()+lightbox()+'</body></html>'

