def floor_rows(which):
    return ''.join(f'<article class="floor-row" data-beds="{b}"><div><span class="floor-bed">{b}<span>BED</span></span></div><div><h3>{b} Bedroom {kind}</h3><p>{desc}</p></div><span class="floor-bath">{bath}</span><a href="/contact.html?property={"Plaza%20East" if which=="plaza" else "SummerHill"}&bedrooms={b}" class="floor-action">Inquire</a></article>' for b,bath,kind,desc in FLOORS[which])

def gallery(which,extra_local=None):
    top_count=12 if which=='plaza' else 10
    gallery_items=[]
    if extra_local:
        for source,description in extra_local:
            gallery_items.append((source,description))
    for i in range(2,top_count+1):
        gallery_items.append((f'property-gallery/{"plaza" if which=="plaza" else "summerhill"}-{i:02d}.webp',f'{"Plaza East" if which=="plaza" else "SummerHill"} residence photograph {i}'))
    content=''.join(f'<button class="gallery-item" type="button" data-caption="{escape(desc,quote=True)}" aria-label="View photo {i+1}: {escape(desc,quote=True)}" {"data-hidden=true" if i>=6 else ""}>{img(source,desc)}<span class="gallery-item-index">{i+1:02d}</span></button>' for i,(source,desc) in enumerate(gallery_items))
    return f'<section class="gallery section" id="gallery"><div class="container"><div class="gallery-top reveal"><div><span class="eyebrow">THE GALLERY / 03</span><h2>Inside {"Plaza East" if which=="plaza" else "SummerHill"}.</h2></div><span class="gallery-total">{len(gallery_items):02d} PHOTOGRAPHS</span></div><div class="gallery-grid" data-gallery>{content}</div><button type="button" class="gallery-more button-outline" aria-expanded="false">View all {len(gallery_items)} photographs</button></div></section>'

def property_page(which):
    plaza=which=='plaza'; title='Plaza East' if plaza else 'SummerHill'
    intro='Apartments & townhouses' if plaza else 'Townhouses'
    bds='2, 3 & 4 BEDROOMS' if plaza else '2 & 3 BEDROOMS'
