    facts=[('BEDROOMS','2, 3 & 4' if plaza else '2 & 3'),('RESIDENCE TYPE','Apartments & townhouses' if plaza else 'Townhouses'),('LOCATION','East Hill, Ithaca'),('TOURING','By appointment')]
